namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    VanillaRnnCustomTilingData tiling;

    const auto *xShape = context->GetInputShape(0);
    const auto *hShape = context->GetInputShape(1);

    const int64_t B = xShape->GetOriginShape().GetDim(0);
    const int64_t I = xShape->GetOriginShape().GetDim(1);
    const int64_t H = hShape->GetOriginShape().GetDim(1);

    tiling.set_batch(static_cast<uint32_t>(B));
    tiling.set_input_size(static_cast<uint32_t>(I));
    tiling.set_hidden_size(static_cast<uint32_t>(H));

    // 设置并行block数（可根据实际硬件调优）
    context->SetBlockDim(8);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 本算子不需要额外workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0); // (B, I)
    const gert::Shape* h_shape = context->GetInputShape(1); // (B, H)

    gert::Shape* pre_h_shape = context->GetOutputShape(0);  // (B, H)
    // 输出 pre_h 与 h 的形状一致
    pre_h_shape->SetOriginShape({x_shape->GetOriginShape().GetDim(0), h_shape->GetOriginShape().GetDim(1)});
    pre_h_shape->SetStorageShape(pre_h_shape->GetOriginShape());

    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    // 与输入数据类型对齐
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return GRAPH_SUCCESS;
}
}

